using namespace opencrab2;
using opencrab2::highlevel::Json;
using u64 = uint64_t;

static int g_checks = 0;
static int g_wanted_files = 0;
static int g_skipped_files = 0;

#define CHECK(cond, msg)                                                              \
    do {                                                                              \
        if (!(cond)) {                                                                \
            std::fprintf(stderr, "FAIL: %s (line %d)\n", std::string(msg).c_str(), __LINE__); \
            std::exit(1);                                                             \
        }                                                                             \
        ++g_checks;                                                                   \
    } while (0)

static u64 parse_u64(const Json& j) {
    if (j.is_string()) return std::strtoull(j.as_string().c_str(), nullptr, 10);
    return static_cast<u64>(j.as_int());
}

static int64_t parse_i64(const Json& j) {
    if (j.is_string()) return std::strtoll(j.as_string().c_str(), nullptr, 10);
    return j.as_int();
}

static std::vector<u64> parse_u64_list(const Json& j) {
    std::vector<u64> v;
    for (const Json& e : j.as_array()) v.push_back(parse_u64(e));
    return v;
}

static std::vector<uint8_t> parse_hex(const std::string& h) {
    std::vector<uint8_t> out;
    auto nib = [](char c) -> int {
        if (c >= '0' && c <= '9') return c - '0';
        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
        if (c >= 'A' && c <= 'F') return c - 'A' + 10;
        return -1;
    };
    for (size_t i = 0; i + 1 < h.size(); i += 2) {
        int a = nib(h[i]), b = nib(h[i + 1]);
        if (a < 0 || b < 0) return {};
        out.push_back(static_cast<uint8_t>(a * 16 + b));
    }
    return out;
}

static std::string hex_of(const uint8_t* p, size_t n) {
    static const char* d = "0123456789abcdef";
    std::string s(n * 2, '0');
    for (size_t i = 0; i < n; ++i) {
        s[2 * i] = d[p[i] >> 4];
        s[2 * i + 1] = d[p[i] & 15];
    }
    return s;
}

static u64 reduce_k(u64 v, int k) { return k >= 64 ? v : (v & ((u64(1) << k) - 1)); }

static Expected<Json> load_or_skip(const std::string& dir, const std::string& name) {
    const std::string path = dir + "/" + name;
    ++g_wanted_files;
    std::ifstream probe(path);
    if (!probe) {
        std::printf("SKIP %s: file missing, run python cpp/tests/gen_vectors.py\n", name.c_str());
        ++g_skipped_files;
        return Expected<Json>::failure("MISSING");
    }
    probe.close();
    Expected<Json> j = Json::load_file(path);
    CHECK(j.ok, "parse " + name + ": " + j.code);
    return j;
}

// ---------------------------------------------------------------------------
static void test_prg(const Json& root) {
    CHECK(root.get("format").as_string() == "opencrab2-prg-vectors-v1", "prg format");
    const auto& cases = root.get("cases").as_array();
    CHECK(cases.size() >= 17, "prg cases");
    for (const Json& c : cases) {
        std::vector<uint8_t> seed = parse_hex(c.get("seed").as_string());
        CHECK(seed.size() == 16, "prg seed length");
        uint8_t out[64];
        lowlevel::expand_bytes(seed.data(), out);
        CHECK(hex_of(out, 64) == c.get("out").as_string(), "prg expansion of seed " + c.get("seed").as_string());
        lowlevel::Expansion e = lowlevel::expand(seed.data());
        uint8_t sl[16], sr[16];
        lowlevel::block_to_bytes(e.sL, sl);
        lowlevel::block_to_bytes(e.sR, sr);
        CHECK(hex_of(sl, 16) == c.get("sL").as_string() && hex_of(sr, 16) == c.get("sR").as_string(), "prg sL/sR");
        CHECK(e.vL == parse_u64(c.get("vL")) && e.vR == parse_u64(c.get("vR")), "prg vL/vR");
        CHECK(e.tL == static_cast<u64>(c.get("tL").as_int()) && e.tR == static_cast<u64>(c.get("tR").as_int()), "prg tL/tR");
    }
    std::printf("  prg: %zu seeds ok\n", cases.size());
}

// ---------------------------------------------------------------------------
static void test_dcf(const Json& root) {
    using namespace lowlevel::dcf;
    CHECK(root.get("format").as_string() == "opencrab2-dcf-vectors-v1", "dcf format");
    const auto& cases = root.get("cases").as_array();
    CHECK(cases.size() >= 8, "dcf cases");
    bool saw_p[4] = {false, false, false, false}, saw_ring = false, saw_zt = false;
    for (const Json& c : cases) {
        const std::string name = c.get("name").as_string();
        const u64 modulus = parse_u64(c.get("modulus"));
        const int n_bits = static_cast<int>(c.get("n_bits").as_int());
        const int P = static_cast<int>(c.get("P").as_int());
        std::vector<u64> alpha = parse_u64_list(c.get("alpha"));
        std::vector<u64> beta = parse_u64_list(c.get("beta"));
        std::vector<u64> x = parse_u64_list(c.get("x"));
        std::vector<u64> expected = parse_u64_list(c.get("expected"));
        std::vector<u64> out[2];
        for (int p = 0; p < 2; ++p) {
            std::vector<uint8_t> kb = parse_hex(c.get(p == 0 ? "key0" : "key1").as_string());
            Expected<DcfKeyBatch> key = DcfKeyBatch::from_bytes(kb);
            CHECK(key.ok, name + ": parse python key: " + key.code);
            CHECK(key.value.party == p && key.value.n_bits == n_bits && key.value.P == P && key.value.modulus == modulus &&
                      key.value.M() == alpha.size(),
                  name + ": key header fields");
            CHECK(kb.size() >= WIRE_HEADER_BYTES && kb[0] == WIRE_VERSION, name + ": the Python key uses the binding layout (wire version 2)");
            CHECK(key.value.to_bytes() == kb, name + ": re-serialization in the binding layout is byte-identical");
            Expected<std::vector<u64>> o = eval_dcf_batch(key.value, x);
            CHECK(o.ok, name + ": eval: " + o.code);
            std::vector<u64> want = parse_u64_list(c.get(p == 0 ? "out0" : "out1"));
            CHECK(o.value == want, name + ": party " + std::to_string(p) + " output shares equal the Python shares");
            out[p] = o.value;
        }
        if (P >= 1 && P <= 3) saw_p[P] = true;
        (modulus ? saw_zt : saw_ring) = true;
        Expected<std::vector<u64>> rec = reconstruct_dcf(out[0], out[1], modulus);
        CHECK(rec.ok && rec.value == expected, name + ": reconstruction equals beta 1{x < alpha}");
        for (size_t m = 0; m < alpha.size(); ++m)
            for (int p = 0; p < P; ++p) {
                u64 want = x[m] < alpha[m] ? (modulus ? beta[m * P + p] % modulus : beta[m * P + p]) : 0;
                CHECK(expected[m * P + p] == want, name + ": expected column is consistent");
            }
    }
    CHECK(saw_p[1] && saw_p[2] && saw_p[3] && saw_ring && saw_zt, "dcf vectors cover P in {1, 2, 3} and both payload groups");
    std::printf("  dcf: %zu key batches ok\n", cases.size());
}

// ---------------------------------------------------------------------------
static void test_trunc(const Json& root) {
    using namespace lowlevel::trunc;
    CHECK(root.get("format").as_string() == "opencrab2-trunc-vectors-v1", "trunc format");
    const auto& cases = root.get("cases").as_array();
    CHECK(cases.size() >= 3, "trunc cases");
    size_t elements = 0;
    for (const Json& c : cases) {
        const std::string name = c.get("name").as_string();
        const int k = static_cast<int>(c.get("k").as_int());
        const int L = static_cast<int>(c.get("L").as_int());
        const int f = static_cast<int>(c.get("f").as_int());
        std::vector<u64> xs[2] = {parse_u64_list(c.get("x0")), parse_u64_list(c.get("x1"))};
        std::vector<u64> y = parse_u64_list(c.get("y"));
        std::vector<u64> out[2];
        std::vector<u64> open_sum(y.size(), 0);
        for (int p = 0; p < 2; ++p) {
            std::vector<uint8_t> mb = parse_hex(c.get(p == 0 ? "material0" : "material1").as_string());
            Expected<TruncMaterial> mat = TruncMaterial::from_bytes(mb);
            CHECK(mat.ok, name + ": parse python material: " + mat.code);
            CHECK(mat.value.party == p && mat.value.f == f && mat.value.L == L && mat.value.k() == k && mat.value.M() == y.size(),
                  name + ": material header");
            Expected<std::vector<u64>> msg = trunc_open_share(xs[p], mat.value, p);
            CHECK(msg.ok, name + ": open share: " + msg.code);
            for (size_t m = 0; m < y.size(); ++m) open_sum[m] = reduce_k(open_sum[m] + msg.value[m], k);
            Expected<std::vector<u64>> o = trunc_faithful_eval(mat.value, y, p);
            CHECK(o.ok, name + ": eval: " + o.code);
            CHECK(o.value == parse_u64_list(c.get(p == 0 ? "out0" : "out1")), name + ": party " + std::to_string(p) + " output share");
            out[p] = o.value;
        }
        CHECK(open_sum == y, name + ": the opened y equals the Python y");
        const auto& exp = c.get("expected_signed").as_array();
        const auto& xsig = c.get("x_signed").as_array();
        for (size_t m = 0; m < y.size(); ++m) {
            int64_t want = parse_i64(exp[m]);
            u64 z = reduce_k(out[0][m] + out[1][m], k);
            int64_t got = (k < 64 && z >= (u64(1) << (k - 1))) ? static_cast<int64_t>(z) - static_cast<int64_t>(u64(1) << k)
                                                                : static_cast<int64_t>(z);
            CHECK(got == want, name + ": reconstruction equals floor(x / 2^f) for x = " + xsig[m].as_string());
            int64_t xv = parse_i64(xsig[m]);
            CHECK(want == (xv >> f), name + ": expected column is floor division");
        }
        elements += y.size();
    }
    std::printf("  trunc: %zu cases, %zu elements ok\n", cases.size(), elements);
}

// ---------------------------------------------------------------------------
static void test_r2f(const Json& root) {
    using namespace lowlevel::r2f;
    CHECK(root.get("format").as_string() == "opencrab2-r2f-vectors-v1", "r2f format");
    const auto& cases = root.get("cases").as_array();
    CHECK(cases.size() >= 3, "r2f cases");
    for (const Json& c : cases) {
        const std::string name = c.get("name").as_string();
        const int k = static_cast<int>(c.get("k").as_int());
        const u64 t = parse_u64(c.get("t"));
        std::vector<u64> a[2] = {parse_u64_list(c.get("a0")), parse_u64_list(c.get("a1"))};
        std::vector<u64> y = parse_u64_list(c.get("y"));
        std::vector<u64> expected = parse_u64_list(c.get("expected"));
        std::vector<u64> out[2];
        std::vector<u64> open_sum(y.size(), 0);
        for (int p = 0; p < 2; ++p) {
            std::vector<uint8_t> mb = parse_hex(c.get(p == 0 ? "material0" : "material1").as_string());
            Expected<R2FMaterial> mat = R2FMaterial::from_bytes(mb);
            CHECK(mat.ok, name + ": parse python material: " + mat.code);
            CHECK(mat.value.party == p && mat.value.t == t && mat.value.k() == k && mat.value.M() == y.size(), name + ": material header");
            Expected<std::vector<u64>> msg = r2f_open_share(a[p], mat.value, p);
            CHECK(msg.ok, name + ": open share: " + msg.code);
            for (size_t m = 0; m < y.size(); ++m) open_sum[m] = reduce_k(open_sum[m] + msg.value[m], k);
            Expected<std::vector<u64>> o = r2f_eval(mat.value, y, p);
            CHECK(o.ok, name + ": eval: " + o.code);
            CHECK(o.value == parse_u64_list(c.get(p == 0 ? "out0" : "out1")), name + ": party " + std::to_string(p) + " output share");
            out[p] = o.value;
        }
        CHECK(open_sum == y, name + ": the opened y equals the Python y");
        for (size_t m = 0; m < y.size(); ++m) {
            u64 z = (out[0][m] + out[1][m]) % t;   // both below t < 2^62, no overflow
            CHECK(z == expected[m], name + ": reconstruction equals x_signed mod t");
            u64 u = reduce_k(a[0][m] + a[1][m], k);
            CHECK(signed_mod(u, t, k) == expected[m], name + ": expected column equals the C++ plaintext reference");
        }
    }
    std::printf("  r2f: %zu cases ok\n", cases.size());
}

// ---------------------------------------------------------------------------
static bool approx_eq(double a, double b, double tol) { return std::fabs(a - b) <= tol * std::max(1.0, std::max(std::fabs(a), std::fabs(b))); }

// The decision of one vector instance against its recorded fields (chosen, switched, Qhat(keep);
// q_best, lower bound and U_diff when switched). Returns the switched flag.
static bool check_decision(const highlevel::Decision& d, const Json& want, const std::string& id) {
    using namespace highlevel;
    CHECK(same_plan(d.chosen, want.get("chosen")), id + ": chosen plan equals the Python decision");
    CHECK(d.switched == want.get("switched").as_bool(), id + ": switched flag equals the Python decision");
    CHECK(approx_eq(d.q_keep, want.get("q_keep").as_double(), 1e-9), id + ": Qhat(keep)");
    if (d.switched && want.has("q_best")) {
        CHECK(approx_eq(d.q_best, want.get("q_best").as_double(), 1e-9), id + ": Qhat(chosen)");
        CHECK(approx_eq(d.lower_bound_gain, want.get("lower_bound_gain").as_double(), 1e-9), id + ": lower bound gain");
        CHECK(approx_eq(d.u_diff, want.get("u_diff").as_double(), 1e-9), id + ": U_diff");
    }
    return d.switched;
}

static void test_controller(const Json& root) {
    using namespace highlevel;
    CHECK(root.get("format").as_string() == "opencrab2-controller-vectors-python-v1", "controller format");
    const auto& instances = root.get("instances").as_array();
    CHECK(instances.size() >= 20, "controller instances");
    int switched = 0, scheduled = 0, differs = 0;
    for (const Json& inst : instances) {
        const std::string id = "instance " + std::to_string(inst.get("id").as_int());
        Expected<ControllerConfig> cfg = ControllerConfig::from_json(inst.get("config"));
        CHECK(cfg.ok, id + ": config: " + cfg.code);
        Expected<SessionState> st = SessionState::from_json(inst.get("state"));
        CHECK(st.ok, id + ": state: " + st.code);
        std::vector<Candidate> cands;
        bool has_schedule = false;
        for (const Json& cj : inst.get("candidates").as_array()) {
            Expected<Candidate> c = Candidate::from_json(cj);
            CHECK(c.ok, id + ": candidate: " + c.code);
            if (!c.value.exec_s_by_epoch.empty()) {
                has_schedule = true;
                CHECK(c.value.exec_s_by_epoch.size() == c.value.exec_sigma_by_epoch.size(), id + ": per-step lists of equal length");
                CHECK(c.value.exec_s_by_epoch[0] == c.value.exec_s_per_epoch && c.value.exec_sigma_by_epoch[0] == c.value.exec_sigma,
                      id + ": entry 0 of the per-step lists is the current epoch");
            }
            cands.push_back(c.value);
        }
        std::vector<double> surv;
        for (const Json& s : inst.get("survival").as_array()) surv.push_back(s.as_double());
        CHECK(surv.size() == static_cast<size_t>(st.value.remaining_epochs), id + ": survival length equals the horizon");
        {
            // one dwell model in both languages: the C++ survival fitted on the instance's telemetry is the stored one
            StateAwareController fit(cfg.value);
            for (const Json& tj : inst.get("telemetry").as_array()) {
                Expected<TelemetrySample> s = TelemetrySample::from_json(tj);
                CHECK(s.ok, id + ": telemetry: " + s.code);
                if (s.ok) fit.observe(s.value);
            }
            const std::vector<double> own = fit.survival(static_cast<int>(surv.size()));
            bool same = own.size() == surv.size();
            for (std::size_t k = 0; same && k < own.size(); ++k) same = approx_eq(own[k], surv[k], 1e-12);
            CHECK(same, id + ": the C++ dwell model reproduces the survival vector");
        }
        const int epoch = static_cast<int>(inst.get("epoch").as_int());
        StateAwareController ctl(cfg.value);
        Expected<Decision> d = ctl.decide_with_survival(st.value, cands, epoch, surv);
        CHECK(d.ok, id + ": decide: " + d.code);
        if (check_decision(d.value, inst.get("decision"), id)) ++switched;
        if (has_schedule) {
            // the lists decide: with them dropped, the controller takes the recorded one-shape decision
            ++scheduled;
            CHECK(inst.has("single_shape"), id + ": a scheduled instance records its one-shape decision");
            std::vector<Candidate> flat = cands;
            for (Candidate& c : flat) {
                c.exec_s_by_epoch.clear();
                c.exec_sigma_by_epoch.clear();
            }
            StateAwareController one(cfg.value);
            Expected<Decision> od = one.decide_with_survival(st.value, flat, epoch, surv);
            CHECK(od.ok, id + ": one-shape decide: " + od.code);
            const Json& single = inst.get("single_shape");
            check_decision(od.value, single, id + " (one shape)");
            const bool diff = !same_plan(d.value.chosen, od.value.chosen) || d.value.switched != od.value.switched;
            CHECK(diff == single.get("differs").as_bool(), id + ": the recorded 'differs' flag of the one-shape decision");
            if (diff) ++differs;
        }
    }
    CHECK(switched >= 3, "the vector set contains switching decisions");
    if (root.has("instances_switching")) CHECK(switched == root.get("instances_switching").as_int(), "the number of switching instances is the recorded one");
    if (root.has("instances_scheduled")) {
        CHECK(scheduled == root.get("instances_scheduled").as_int() && scheduled > 0, "the number of scheduled instances is the recorded one");
        CHECK(differs == root.get("instances_scheduled_single_shape_differs").as_int() && differs > 0,
              "one-shape pricing differs from the per-step decision on the recorded number of instances");
    }
    std::printf("  controller: %zu instances ok (%d switch, %d scheduled, %d where one-shape pricing differs)\n", instances.size(), switched,
                scheduled, differs);
}

