static void test_telemetry(const Json& root) {
    using namespace highlevel;
    CHECK(root.get("format").as_string() == "opencrab2-telemetry-vectors-v1", "telemetry format");
    CHECK(root.get("min_net_s").as_double() == PROBE_MIN_NET_S, "telemetry: the floor of the net burst time is shared");
    const double cap = root.get("max_bandwidth_bps").as_double();
    const auto& cases = root.get("cases").as_array();
    CHECK(cases.size() >= 10, "telemetry cases");
    bool saw_floor = false, saw_even = false, saw_cap = false;
    for (const Json& c : cases) {
        const std::string name = "telemetry " + c.get("name").as_string();
        std::vector<double> rtts, els;
        for (const Json& v : c.get("rtt_s").as_array()) rtts.push_back(v.as_double());
        for (const Json& v : c.get("elapsed_s").as_array()) els.push_back(v.as_double());
        const size_t burst = static_cast<size_t>(c.get("burst").as_int());
        Expected<std::pair<double, double>> est = probe_estimate(rtts, els, burst);
        CHECK(est.ok, name + ": estimate: " + est.code);
        CHECK(approx_eq(est.value.first, c.get("bandwidth_bps").as_double(), 1e-12), name + ": pooled bandwidth");
        CHECK(approx_eq(est.value.second, c.get("rtt_median_s").as_double(), 1e-12), name + ": median round-trip time");
        // what sense_epoch puts into the frame: the cap and the floor of the Python sense_and_exchange
        CHECK(approx_eq(std::min(est.value.first, cap), c.get("frame_bandwidth_bps").as_double(), 1e-12), name + ": frame bandwidth (capped)");
        CHECK(approx_eq(std::max(est.value.second, 1e-6), c.get("frame_rtt_s").as_double(), 1e-12), name + ": frame RTT (floored)");
        if (est.value.first == static_cast<double>(burst) * 8.0 / PROBE_MIN_NET_S) saw_floor = true;
        if (rtts.size() % 2 == 0) saw_even = true;
        if (est.value.first > cap) saw_cap = true;
    }
    CHECK(saw_floor && saw_even && saw_cap, "telemetry vectors cover the floor, an even sample count and the cap");
    CHECK(!probe_estimate({}, {}, 4096).ok && !probe_estimate({1.0}, {1.0, 2.0}, 4096).ok && !probe_estimate({1.0}, {2.0}, 0).ok,
          "telemetry: malformed samples are refused");
    std::printf("  telemetry: %zu probes ok\n", cases.size());
}

// ---------------------------------------------------------------------------
// KEY_COMPONENT_INDEPENDENCE attack (the comparison-key finding, paper, Section 5.3), run here on keys generated by
// the OTHER language. A party looks only at the correction words of its own P = 2 key.
struct KciCounts {
    size_t blind_recovered = 0;       // beta_1 in {beta_0 + d, beta_0 - d}, d the first nonzero level difference
    size_t level_equals_delta = 0;    // some level shows d = +-(beta_1 - beta_0)
    size_t alpha_bits_read = 0;       // the nonzero pattern spells alpha
};

template <class CwAt>
static void kci_attack_one(CwAt cw, size_t n, u64 alpha, u64 beta0, u64 beta1, KciCounts& counts) {
    const u64 delta = beta1 - beta0;
    const u64 neg_delta = u64(0) - delta;
    u64 d_first = 0;
    bool hit = false;
    u64 prev_bit = 0, alpha_guess = 0;
    for (size_t i = 0; i < n; ++i) {
        const u64 d = cw(i, 1) - cw(i, 0);
        if (d != 0 && d_first == 0) d_first = d;
        if (d == delta || d == neg_delta) hit = true;
        const u64 bit = prev_bit ^ (d != 0 ? 1u : 0u);
        alpha_guess = (alpha_guess << 1) | bit;
        prev_bit = bit;
    }
    if (d_first != 0 && (beta1 == beta0 + d_first || beta1 == beta0 - d_first)) ++counts.blind_recovered;
    if (hit) ++counts.level_equals_delta;
    if (alpha_guess == alpha) ++counts.alpha_bits_read;
}

// Positive control of the attack code itself: correction words built with the superseded relation
// d_i = +-(a_i - a_{i-1}) (beta_1 - beta_0) must be broken in every trial.
static void kci_positive_control() {
    lowlevel::Rng rng = lowlevel::Rng::from_seed(0x4b434958ULL);
    const size_t n = 32, T = 200;
    KciCounts c;
    for (size_t trial = 0; trial < T; ++trial) {
        const u64 r = rng.next_u64() | 2;   // beta_1 - beta_0 = r - 1 is nonzero
        const u64 alpha = (r & 0xffffffffULL) | 0x80000000ULL;   // the leading bit flips at level 0
        std::vector<u64> cw(2 * n);
        u64 prev = 0;
        for (size_t i = 0; i < n; ++i) {
            const u64 bit = (alpha >> (n - 1 - i)) & 1;
            const u64 w = rng.next_u64();
            const u64 step = (bit - prev) * (r - 1);   // (a_i - a_{i-1}) delta in the ring
            cw[2 * i] = w;
            cw[2 * i + 1] = (rng.next_u64() & 1) ? w + step : w - step;
            prev = bit;
        }
        kci_attack_one([&](size_t i, size_t p) { return cw[2 * i + p]; }, n, alpha, 1, r, c);
    }
    CHECK(c.blind_recovered == T && c.level_equals_delta == T && c.alpha_bits_read == T,
          "KEY_COMPONENT_INDEPENDENCE positive control: the attack breaks shared-word correction words in every trial");
}

static void kci_on_material(const lowlevel::drelu::DreluMaterial& mat, const std::vector<u64>& r, const std::string& what) {
    const size_t T = mat.M();
    const int n = mat.n_bits;
    const u64 dmask = n >= 64 ? ~u64(0) : ((u64(1) << n) - 1);
    const u64 half = u64(1) << (n - 1);
    CHECK(mat.key_p.P == 2 && mat.key_q.P == 2 && mat.key_p.modulus == 0 && r.size() == T && T > 0, what + ": P = 2 DReLU keys over Z_2^64");
    for (int which = 0; which < 2; ++which) {
        const lowlevel::dcf::DcfKeyBatch& key = which == 0 ? mat.key_p : mat.key_q;
        KciCounts c;
        for (size_t m = 0; m < T; ++m) {
            const u64 alpha = (which == 0 ? r[m] : r[m] + half) & dmask;
            kci_attack_one([&](size_t i, size_t p) { return key.cw_values[(i * 2 + p) * T + m]; }, static_cast<size_t>(n), alpha, 1, r[m], c);
        }
        CHECK(c.blind_recovered == 0, what + ": KEY_COMPONENT_INDEPENDENCE blind mask recovery succeeds on 0 keys");
        CHECK(c.level_equals_delta == 0, what + ": KEY_COMPONENT_INDEPENDENCE no level difference equals +-(beta_1 - beta_0)");
        CHECK(c.alpha_bits_read == 0, what + ": KEY_COMPONENT_INDEPENDENCE the nonzero pattern does not spell alpha");
    }
}

