static void test_drelu(const Json& root) {
    using namespace lowlevel::drelu;
    CHECK(root.get("format").as_string() == "opencrab2-drelu-vectors-v1", "drelu format");
    const auto& cases = root.get("cases").as_array();
    CHECK(cases.size() >= 6, "drelu cases");
    for (const Json& c : cases) {
        const std::string name = c.get("name").as_string();
        const int n_bits = static_cast<int>(c.get("n_bits").as_int());
        const bool with_product = c.get("with_product").as_bool();
        std::vector<u64> r = parse_u64_list(c.get("r"));
        std::vector<u64> y = parse_u64_list(c.get("y"));
        DreluOutput out[2];
        std::vector<u64> r_sum(r.size(), 0);
        for (int p = 0; p < 2; ++p) {
            std::vector<uint8_t> mb = parse_hex(c.get(p == 0 ? "material0" : "material1").as_string());
            Expected<DreluMaterial> mat = DreluMaterial::from_bytes(mb);
            CHECK(mat.ok, name + ": parse material: " + mat.code);
            CHECK(mat.value.party == p && mat.value.n_bits == n_bits && mat.value.with_product() == with_product && mat.value.M() == y.size(),
                  name + ": material header");
            CHECK(mat.value.to_bytes() == mb, name + ": re-serialization is byte-identical");
            for (size_t m = 0; m < r.size(); ++m) r_sum[m] += mat.value.r_share[m];
            Expected<DreluOutput> o = drelu_eval(mat.value, y);
            CHECK(o.ok, name + ": eval: " + o.code);
            CHECK(o.value.b == parse_u64_list(c.get(p == 0 ? "b0" : "b1")), name + ": party " + std::to_string(p) + " bit share");
            if (with_product)
                CHECK(o.value.rb == parse_u64_list(c.get(p == 0 ? "rb0" : "rb1")), name + ": party " + std::to_string(p) + " product share");
            out[p] = o.value;
        }
        CHECK(r_sum == r, name + ": the mask shares add up to r");
        const auto& bits = c.get("expected_bit").as_array();
        const auto& xs = c.get("x_signed").as_array();
        for (size_t m = 0; m < y.size(); ++m) {
            const u64 bit = static_cast<u64>(bits[m].as_int());
            CHECK(out[0].b[m] + out[1].b[m] == bit, name + ": reconstruction equals 1{x >= 0}");
            CHECK(bit == (parse_i64(xs[m]) >= 0 ? 1u : 0u), name + ": expected column is the sign of x");
            CHECK(static_cast<u64>(parse_i64(xs[m])) + r[m] == y[m], name + ": y = x + r");
            if (with_product) CHECK(out[0].rb[m] + out[1].rb[m] == r[m] * bit, name + ": reconstruction equals r 1{x >= 0}");
        }
    }
    const Json& kci = root.get("kci");
    CHECK(kci.is_object(), "drelu kci batch present");
    std::vector<uint8_t> mb = parse_hex(kci.get("material").as_string());
    Expected<DreluMaterial> mat = DreluMaterial::from_bytes(mb);
    CHECK(mat.ok, "kci: parse material: " + mat.code);
    CHECK(mat.value.M() == static_cast<size_t>(kci.get("M").as_int()) && mat.value.n_bits == kci.get("n_bits").as_int(), "kci: header");
    kci_positive_control();
    kci_on_material(mat.value, parse_u64_list(kci.get("r")), "kci (" + root.get("origin").as_string() + " keys)");
    std::printf("  drelu: %zu cases ok, KEY_COMPONENT_INDEPENDENCE attack fails on %zu %s keys\n", cases.size(), 2 * mat.value.M(),
                root.get("origin").as_string().c_str());
}

// ---------------------------------------------------------------------------
// Wire codec: tagged description <-> Value
using highlevel::Value;

static Value value_from_tagged(const Json& d) {
    const std::string t = d.get("t").as_string();
    if (t == "none") return Value(highlevel::None{});
    if (t == "bool") return Value(d.get("v").as_bool());
    if (t == "int") return Value(static_cast<int64_t>(std::strtoll(d.get("v").as_string().c_str(), nullptr, 10)));
    if (t == "float") {
        std::vector<uint8_t> b = parse_hex(d.get("hex").as_string());
        CHECK(b.size() == 8, "tagged float carries 8 bytes");
        u64 bits = 0;
        for (int i = 0; i < 8; ++i) bits = (bits << 8) | b[i];
        double v;
        std::memcpy(&v, &bits, 8);
        return Value(v);
    }
    if (t == "str") return Value(d.get("v").as_string());
    if (t == "bytes") return Value(parse_hex(d.get("hex").as_string()));
    if (t == "nd") {
        highlevel::NdArray a;
        a.dtype = static_cast<highlevel::DType>(d.get("dtype").as_int());
        for (const Json& e : d.get("dims").as_array()) a.dims.push_back(static_cast<u64>(e.as_int()));
        a.data = parse_hex(d.get("hex").as_string());
        return Value(a);
    }
    if (t == "dict") {
        highlevel::Dict out;
        for (const Json& kv : d.get("items").as_array()) out.push_back(highlevel::DictEntry{kv[0].as_string(), value_from_tagged(kv[1])});
        return Value(out);
    }
    if (t == "list") {
        highlevel::List out;
        for (const Json& e : d.get("items").as_array()) out.push_back(value_from_tagged(e));
        return Value(out);
    }
    CHECK(false, "unknown tag " + t);
    return Value();
}

static Json tagged_from_value(const Value& v) {
    Json j = Json::object();
    if (v.is_none()) {
        j.set("t", "none");
    } else if (v.is_bool()) {
        j.set("t", "bool");
        j.set("v", v.as_bool().value);
    } else if (v.is_int()) {
        j.set("t", "int");
        j.set("v", std::to_string(static_cast<long long>(v.as_int().value)));
    } else if (v.is_double()) {
        const double dv = std::get<double>(v.v);
        u64 bits;
        std::memcpy(&bits, &dv, 8);
        uint8_t b[8];
        for (int i = 0; i < 8; ++i) b[i] = static_cast<uint8_t>(bits >> (8 * (7 - i)));
        j.set("t", "float");
        j.set("hex", hex_of(b, 8));
    } else if (v.is_string()) {
        j.set("t", "str");
        j.set("v", v.as_string().value);
    } else if (v.is_bytes()) {
        const highlevel::Bytes b = v.as_bytes().value;
        j.set("t", "bytes");
        j.set("hex", hex_of(b.data(), b.size()));
    } else if (v.is_array()) {
        const highlevel::NdArray a = v.as_array().value;
        Json dims = Json::array();
        for (u64 d : a.dims) dims.push_back(static_cast<long long>(d));
        j.set("t", "nd");
        j.set("dtype", static_cast<int>(a.dtype));
        j.set("dims", dims);
        j.set("hex", hex_of(a.data.data(), a.data.size()));
    } else if (v.is_dict()) {
        Json items = Json::array();
        for (const highlevel::DictEntry& e : std::get<highlevel::Dict>(v.v)) {
            Json kv = Json::array();
            kv.push_back(e.key);
            kv.push_back(tagged_from_value(e.val));
            items.push_back(kv);
        }
        j.set("t", "dict");
        j.set("items", items);
    } else {
        Json items = Json::array();
        for (const Value& e : std::get<highlevel::List>(v.v)) items.push_back(tagged_from_value(e));
        j.set("t", "list");
        j.set("items", items);
    }
    return j;
}

static void test_codec(const Json& root) {
    CHECK(root.get("format").as_string() == "opencrab2-codec-vectors-v1", "codec format");
    const auto& cases = root.get("cases").as_array();
    CHECK(cases.size() >= 20, "codec cases");
    bool saw_none = false, saw_bool = false;
    for (const Json& c : cases) {
        const std::string name = c.get("name").as_string();
        const std::vector<uint8_t> payload = parse_hex(c.get("payload_hex").as_string());
        const std::vector<uint8_t> frame = parse_hex(c.get("frame_hex").as_string());
        const Value built = value_from_tagged(c.get("value"));
        CHECK(highlevel::encode_value(built) == payload, name + ": C++ encoding of the described value equals the reference bytes");
        CHECK(highlevel::encode_frame(built) == frame, name + ": framed bytes (u64 BE length prefix) are identical");
        Expected<Value> dec = highlevel::decode_value(payload);
        CHECK(dec.ok, name + ": decode: " + dec.code);
        CHECK(highlevel::encode_value(dec.value) == payload, name + ": decode then encode is byte-identical");
        CHECK(tagged_from_value(dec.value) == c.get("value"), name + ": the decoded value equals the description (types included)");
        if (dec.value.is_none()) {
            saw_none = true;
            CHECK(payload.size() == 1 && payload[0] == 0x08, name + ": none is tag 0x08");
        }
        if (dec.value.is_bool()) {
            saw_bool = true;
            CHECK(payload.size() == 2 && payload[0] == 0x09, name + ": bool is tag 0x09");
        }
    }
    CHECK(saw_none && saw_bool, "codec vectors cover none and bool");
    std::printf("  codec: %zu values ok\n", cases.size());
}

