// ---------------------------------------------------------------------------
// WallClockShaper under the shared rule of channel.hpp (Python-generated cases): delay =
// serialization + one-way delay of the state in force when the last byte leaves; bandwidth 0 =
// unshaped. A fresh shaper per case (the C++ shaper keeps the link-busy time).
static void test_shaper(const Json& root) {
    using namespace highlevel;
    const auto& cases = root.get("cases").as_array();
    CHECK(cases.size() >= 40, "shaper cases");
    for (const Json& c : cases) {
        std::vector<TracePoint> tr;
        for (const Json& pt : c.get("points").as_array()) {
            const auto& a = pt.as_array();
            tr.push_back(TracePoint{a[0].as_double(), LinkState{a[1].as_double(), a[2].as_double()}});
        }
        const double origin = c.get("origin").as_double(), wall = c.get("wall_s").as_double();
        const std::size_t nbytes = static_cast<std::size_t>(c.get("nbytes").as_int());
        auto sh = WallClockShaper::make(tr, origin);
        CHECK(sh.ok, "shaper: trace accepted: " + sh.code);
        const double want = c.get("delay_s").as_double(), want_ser = c.get("serialization_s").as_double();
        const double ser = sh.value->serialization_time(nbytes, wall);
        const double got = sh.value->delay_for(nbytes, wall);
        const std::string id = "shaper nbytes " + std::to_string(nbytes) + " wall " + std::to_string(wall);
        CHECK(std::fabs(got - want) <= 1e-9 * (1.0 + std::fabs(want)), id + ": delay file " + std::to_string(want) + ", cpp " + std::to_string(got));
        CHECK(std::fabs(ser - want_ser) <= 1e-9 * (1.0 + std::fabs(want_ser)), id + ": serialization");
    }
    std::printf("  shaper: %zu cases ok\n", cases.size());
}

