static void test_costmodel(const Json& root) {
    using namespace highlevel;
    CHECK(root.get("format").as_string() == "opencrab2-costmodel-vectors-v1", "costmodel format");
    Expected<FittedCostModel> model = FittedCostModel::from_json(root.get("model"));
    CHECK(model.ok, "costmodel: model: " + model.code);
    std::vector<Env> envs;
    for (const Json& e : root.get("envs").as_array()) {
        Expected<Env> env = Env::from_json(e);
        CHECK(env.ok, "costmodel: env: " + env.code);
        envs.push_back(env.value);
    }
    const NumericContract nc = default_contract();
    const Json& f = root.get("formulas");
    const FormulaConstants fc = formula_constants();
    CHECK(f.get("bfv_ct_bytes").as_int() == fc.bfv_ciphertext_bytes, "costmodel: BFV ciphertext bytes");
    CHECK(f.get("frame_bytes").as_int() == fc.frame_bytes, "costmodel: frame bytes");
    CHECK(f.get("drelu_p1_bytes").as_int() == drelu_material_bytes(nc, 1) && f.get("drelu_p2_bytes").as_int() == drelu_material_bytes(nc, 2),
          "costmodel: DReLU material bytes");
    CHECK(f.get("trunc_faithful_bytes").as_int() == trunc_material_bytes(nc) && f.get("ring_to_field_bytes").as_int() == r2f_material_bytes(),
          "costmodel: truncation and ring_to_field material bytes");
    if (f.has("formulas_json_constants")) {
        const Json& k = f.get("formulas_json_constants");
        CHECK(f.get("formulas_json_ct_bytes").as_int() == fc.bfv_ciphertext_bytes, "formulas.json: ct_bytes");
        CHECK(k.get("drelu_p1_bytes").as_int() == drelu_material_bytes(nc, 1) && k.get("drelu_p2_bytes").as_int() == drelu_material_bytes(nc, 2) &&
                  k.get("trunc_faithful_bytes").as_int() == trunc_material_bytes(nc) && k.get("ring_to_field_bytes").as_int() == r2f_material_bytes() &&
                  k.get("OPEN_BYTES").as_int() == kOpenBytes && k.get("BEAVER_OPEN_BYTES").as_int() == kBeaverOpenBytes &&
                  k.get("ONEWAY_BYTES").as_int() == kOnewayBytes && k.get("BFV_N").as_int() == fc.bfv_slots,
              "formulas.json: shared constants");
    }
    const auto& cases = root.get("cases").as_array();
    CHECK(cases.size() >= 30, "costmodel cases");
    size_t n_pred = 0;
    for (const Json& c : cases) {
        const std::string comp = c.get("component").as_string();
        const std::int64_t n = c.get("n").as_int(), d_in = c.get("d_in").as_int(), d_out = c.get("d_out").as_int();
        const std::string id = comp + " (" + std::to_string(n) + ", " + std::to_string(d_in) + ", " + std::to_string(d_out) + ")";
        auto eq = [&](const Expected<std::int64_t>& got, const char* key) {
            CHECK(got.ok, id + " " + key + ": " + got.code);
            CHECK(got.value == c.get(key).as_int(),
                  id + " " + key + ": file " + std::to_string(c.get(key).as_int()) + ", cpp " + std::to_string(got.value));
        };
        eq(bytes_formula(comp, n, d_in, d_out), "bytes");
        eq(payload_bytes(comp, n, d_in, d_out), "payload_bytes");
        eq(rounds_formula(comp, n, d_in, d_out), "rounds");
        eq(messages_formula(comp, n, d_in, d_out), "messages");
        eq(macs(comp, n, d_in, d_out), "macs");
        eq(material_formula(comp, n, d_in, d_out, nc), "material_bytes");
        const auto& preds = c.get("predictions").as_array();
        CHECK(preds.size() == envs.size(), id + ": one prediction per environment");
        for (size_t e = 0; e < envs.size(); ++e) {
            Expected<Prediction> p = model.value.predict(comp, n, d_in, d_out, envs[e]);
            CHECK(p.ok, id + ": predict: " + p.code);
            CHECK(approx_eq(p.value.mean_s, preds[e].get("mean_s").as_double(), 1e-9), id + ": predicted mean, env " + std::to_string(e));
            CHECK(approx_eq(p.value.sigma_s, preds[e].get("sigma_s").as_double(), 1e-9), id + ": predicted sigma, env " + std::to_string(e));
            ++n_pred;
        }
    }
    const auto& tour = root.get("tournament").as_array();
    CHECK(tour.size() >= 30, "costmodel tournament vectors");
    for (const Json& t : tour) {
        const TournamentCounts tc = tournament_counts(t.get("n").as_int(), static_cast<int>(t.get("k").as_int()), t.get("with_index").as_bool());
        const std::string id = "tournament n=" + std::to_string(t.get("n").as_int()) + " k=" + std::to_string(t.get("k").as_int());
        CHECK(tc.levels == t.get("levels").as_int() && tc.rounds == t.get("rounds").as_int(), id + ": levels and rounds (2 per level)");
        CHECK(tc.comparisons == t.get("drelu_p1").as_int(), id + ": pairwise comparisons (P = 1)");
        CHECK(tc.payload_drelu == t.get("drelu_p2").as_int(), id + ": payload DReLUs of the fused nodes (P = 2)");
        CHECK(tc.selects == t.get("beaver_select").as_int(), id + ": Beaver selects of the binary nodes");
    }
    std::printf("  costmodel: %zu shapes, %zu predictions, %zu tournaments ok\n", cases.size(), n_pred, tour.size());
}

