static void emit_drelu(const std::string& path, size_t kci_keys) {
    using namespace lowlevel::drelu;
    lowlevel::Rng rng = lowlevel::Rng::from_seed(0x4452454c5532ULL);
    Json cases = Json::array();
    for (int n_bits : {8, 32, 64}) {
        for (bool with_product : {false, true}) {
            const int64_t lim = int64_t(1) << (std::min(n_bits, 62) - 1);
            std::vector<int64_t> xs = {0, -1, 1, lim - 1, -lim};
            for (int i = 0; i < 5; ++i) xs.push_back(static_cast<int64_t>(rng.next_u64() % static_cast<u64>(2 * lim)) - lim);
            const size_t M = xs.size();
            std::vector<u64> r(M), y(M);
            for (size_t m = 0; m < M; ++m) {
                r[m] = rng.next_u64();
                y[m] = static_cast<u64>(xs[m]) + r[m];
            }
            auto mats = drelu_material_from_mask(r, n_bits, rng, with_product);
            CHECK(mats.ok, "emit drelu: material: " + mats.code);
            auto o0 = drelu_eval(mats.value.first, y);
            auto o1 = drelu_eval(mats.value.second, y);
            CHECK(o0.ok && o1.ok, "emit drelu: eval");
            Json c = Json::object(), xj = Json::array(), bits = Json::array();
            for (size_t m = 0; m < M; ++m) {
                xj.push_back(std::to_string(static_cast<long long>(xs[m])));
                bits.push_back(xs[m] >= 0 ? 1 : 0);
                CHECK(o0.value.b[m] + o1.value.b[m] == (xs[m] >= 0 ? 1u : 0u), "emit drelu: C++ self-check");
            }
            c.set("name", "drelu_n" + std::to_string(n_bits) + "_p" + (with_product ? "2" : "1"));
            c.set("n_bits", n_bits);
            c.set("with_product", with_product);
            c.set("M", static_cast<long long>(M));
            c.set("r", str_list(r));
            c.set("x_signed", xj);
            c.set("y", str_list(y));
            const std::vector<uint8_t> b0 = mats.value.first.to_bytes(), b1 = mats.value.second.to_bytes();
            c.set("material0", hex_of(b0.data(), b0.size()));
            c.set("material1", hex_of(b1.data(), b1.size()));
            c.set("b0", str_list(o0.value.b));
            c.set("b1", str_list(o1.value.b));
            c.set("rb0", str_list(with_product ? o0.value.rb : std::vector<u64>{}));
            c.set("rb1", str_list(with_product ? o1.value.rb : std::vector<u64>{}));
            c.set("expected_bit", bits);
            cases.push_back(c);
        }
    }
    std::vector<u64> r(kci_keys);
    for (u64& v : r) v = rng.next_u64();
    auto mats = drelu_material_from_mask(r, 32, rng, true);
    CHECK(mats.ok, "emit drelu: kci material: " + mats.code);
    const std::vector<uint8_t> kb = mats.value.first.to_bytes();
    Json kci = Json::object();
    kci.set("description", "P = 2 DReLU material of party 0 only and the masks r, for the blind attack on the comparison keys (paper, Section 5.3)");
    kci.set("n_bits", 32);
    kci.set("M", static_cast<long long>(kci_keys));
    kci.set("party", 0);
    kci.set("r", str_list(r));
    kci.set("material", hex_of(kb.data(), kb.size()));
    Json root = Json::object();
    root.set("format", "opencrab2-drelu-vectors-v1");
    root.set("origin", "cpp");
    root.set("generator", "cpp/tests/test_vectors.cpp --emit (opencrab2::lowlevel::drelu)");
    root.set("material_layout", "OC2DRL01 container with DCF keys in the binding layout (wire version 2)");
    root.set("cases", cases);
    root.set("kci", kci);
    save_json(path, root);
}

static void emit_codec(const std::string& path) {
    using namespace highlevel;
    std::vector<std::pair<std::string, Value>> vals;
    vals.push_back({"none", Value(None{})});
    vals.push_back({"bool_true", Value(true)});
    vals.push_back({"bool_false", Value(false)});
    vals.push_back({"int_small", Value(int64_t(5))});
    vals.push_back({"int_minus_one", Value(int64_t(-1))});
    vals.push_back({"int_max", Value(INT64_MAX)});
    vals.push_back({"int_min", Value(INT64_MIN)});
    vals.push_back({"float", Value(1.5)});
    vals.push_back({"float_neg_zero", Value(-0.0)});
    vals.push_back({"float_third", Value(1.0 / 3.0)});
    vals.push_back({"str_ascii", Value(std::string("ab"))});
    vals.push_back({"str_utf8", Value(std::string("h\xc3\xa9llo \xe4\xb8\x96\xe7\x95\x8c"))});
    vals.push_back({"str_empty", Value(std::string())});
    vals.push_back({"bytes", Value(Bytes{0x61, 0x62})});
    vals.push_back({"bytes_empty", Value(Bytes{})});
    Bytes all(256);
    for (int i = 0; i < 256; ++i) all[i] = static_cast<uint8_t>(i);
    vals.push_back({"bytes_all", Value(all)});
    vals.push_back({"nd_u64_1d", u64_array({1, 2, ~u64(0)}, {3})});
    vals.push_back({"nd_u64_2d", u64_array({11, 12, 13, 21, 22, 0x8000000000000001ULL}, {2, 3})});
    vals.push_back({"nd_f64", f64_array({1.5, -2.25}, {2})});
    vals.push_back({"nd_u8_2d", Value(NdArray::from_u8(Bytes{1, 2, 3, 4, 5, 6}, {2, 3}))});
    {
        NdArray a;
        a.dtype = DType::i32;
        a.dims = {2};
        a.data = Bytes{0xfe, 0xff, 0xff, 0xff, 7, 0, 0, 0};
        vals.push_back({"nd_i32", Value(a)});
        NdArray b;
        b.dtype = DType::i64;
        b.dims = {1};
        b.data = Bytes(8, 0xff);
        vals.push_back({"nd_i64", Value(b)});
    }
    vals.push_back({"nd_empty", u64_array({}, {0})});
    vals.push_back({"list_bool_none", Value(List{Value(true), Value(None{}), Value(false)})});
    vals.push_back({"list_empty", Value(List{})});
    vals.push_back({"dict_none", dict({{"k", Value(None{})}})});
    vals.push_back({"dict_empty", Value(Dict{})});
    vals.push_back({"dict_order", dict({{"zeta", Value(1)}, {"alpha", Value(2)}, {"mid", Value(3)}})});
    vals.push_back({"req_header", dict({{"type", Value("REQ")}, {"count", Value(1)}, {"final", Value(false)}, {"note", Value(None{})}})});
    vals.push_back({"bundle_header",
                    dict({{"type", Value("BUNDLE")},
                          {"params", dict({{"shape_a", Value(List{Value(2), Value(3)})}, {"shape_b", Value(List{Value(3), Value(4)})},
                                           {"shape", Value(List{Value(4), Value(5)})}, {"bound", Value(512.0)}, {"mask", Value(None{})}})},
                          {"tag", Value(Bytes(32, 0xa5))},
                          {"last", Value(true)}})});
    vals.push_back({"nested", dict({{"a", Value(List{dict({{"b", Value(List{Value(None{}), Value(true), dict({{"c", u64_array({7}, {1})}})})}}),
                                                     Value(2.5), Value("x")})},
                                    {"d", dict({{"e", dict({{"f", Value(List{})}})}})}})});
    Json cases = Json::array();
    for (const auto& nv : vals) {
        const Bytes payload = encode_value(nv.second);
        const Bytes frame = encode_frame(nv.second);
        Json c = Json::object();
        c.set("name", nv.first);
        c.set("value", tagged_from_value(nv.second));
        c.set("payload_hex", hex_of(payload.data(), payload.size()));
        c.set("frame_hex", hex_of(frame.data(), frame.size()));
        cases.push_back(c);
    }
    Json root = Json::object();
    root.set("format", "opencrab2-codec-vectors-v1");
    root.set("origin", "cpp");
    root.set("generator", "cpp/tests/test_vectors.cpp --emit (opencrab2::highlevel::encode_value)");
    root.set("frame", "u64 big-endian payload length, then the payload");
    root.set("cases", cases);
    save_json(path, root);
}

static void emit_contract(const std::string& path) {
    using namespace highlevel;
    std::vector<std::pair<std::string, NumericContract>> cs;
    cs.push_back({"default", default_contract()});
    cs.push_back({"smollm", smollm_contract()});
    NumericContract a = default_contract();
    a.exp_r = 6;
    a.exp_extra_bits = 5;
    a.name = "NC-test-cpp-exp";
    cs.push_back({"variant_exp", a});
    NumericContract b = default_contract();
    b.logical_bits = 44;
    b.name = "NC-test-cpp-l44";
    cs.push_back({"variant_l44", b});
    NumericContract c3 = default_contract();
    c3.recip_newton = 3;
    c3.rsqrt_newton = 3;
    c3.name = "NC-test-cpp-newton";
    cs.push_back({"variant_newton", c3});
    Json cases = Json::array();
    for (const auto& nc : cs) {
        CHECK(nc.second.validate().ok, "emit contract: " + nc.first + " validates");
        const std::string canon = nc.second.to_json().dump();
        Json c = Json::object();
        c.set("name", nc.first);
        c.set("contract_name", nc.second.name);
        c.set("json", nc.second.to_json());
        c.set("hash", nc.second.contract_hash());
        c.set("canonical_hex", hex_of(reinterpret_cast<const uint8_t*>(canon.data()), canon.size()));
        cases.push_back(c);
    }
    Json root = Json::object();
    root.set("format", "opencrab2-contract-vectors-v1");
    root.set("origin", "cpp");
    root.set("generator", "cpp/tests/test_vectors.cpp --emit (opencrab2::highlevel::NumericContract)");
    root.set("cases", cases);
    save_json(path, root);
}

static void emit_costmodel(const std::string& path) {
    using namespace highlevel;
    const NumericContract nc = default_contract();
    FittedCostModel model;
    model.rel_bw = 0.125;
    model.rel_rtt = 0.0625;
    model.label = "MODELED";
    int i = 0;
    for (const std::string& comp : components()) {
        ComponentFit fit;
        fit.compute_per_mac_s = (5 + i) * std::ldexp(1.0, -35);
        fit.compute_per_byte_s = (1 + (i % 3)) * std::ldexp(1.0, -30);
        fit.compute_fixed_s = (3 + 2 * i) * std::ldexp(1.0, -11);
        fit.sigma_compute_s = (2 + i) * std::ldexp(1.0, -12);
        fit.n_train = 3 + i;
        fit.status = "MODELED";
        fit.source = "test_vectors --emit";
        model.fits[comp] = fit;
        ++i;
    }
    std::vector<Env> envs(4);
    envs[0] = Env{0.0, 0.0, 1.0};
    envs[1] = Env{1.0e9, 0.0005, 1.0};
    envs[2] = Env{5.0e7, 0.02, 1.0};
    envs[3] = Env{2.0e8, 0.005, 0.25};
    Json envs_j = Json::array();
    for (const Env& e : envs) {
        Json ej = Json::object();
        ej.set("bandwidth_bps", e.bandwidth_bps);
        ej.set("one_way_latency_s", e.one_way_latency_s);
        ej.set("cpu_share", e.cpu_share);
        envs_j.push_back(ej);
    }
    const Json doc = formulas_document(nc);
    Json cases = Json::array();
    for (const Json& s : doc.get("shapes").as_array()) {
        const std::string comp = s.get("component").as_string();
        const std::int64_t n = s.get("n").as_int(), d_in = s.get("d_in").as_int(), d_out = s.get("d_out").as_int();
        Json c = Json::object();
        c.set("component", comp);
        c.set("n", static_cast<long long>(n));
        c.set("d_in", static_cast<long long>(d_in));
        c.set("d_out", static_cast<long long>(d_out));
        auto put = [&](const char* key, const Expected<std::int64_t>& v) {
            CHECK(v.ok, std::string("emit costmodel ") + comp + " " + key + ": " + v.code);
            c.set(key, static_cast<long long>(v.value));
        };
        put("bytes", bytes_formula(comp, n, d_in, d_out));
        put("payload_bytes", payload_bytes(comp, n, d_in, d_out));
        put("rounds", rounds_formula(comp, n, d_in, d_out));
        put("messages", messages_formula(comp, n, d_in, d_out));
        put("macs", macs(comp, n, d_in, d_out));
        put("material_bytes", material_formula(comp, n, d_in, d_out, nc));
        Json preds = Json::array();
        for (const Env& e : envs) {
            Expected<Prediction> p = model.predict(comp, n, d_in, d_out, e);
            CHECK(p.ok, "emit costmodel predict: " + p.code);
            Json pj = Json::object();
            pj.set("mean_s", p.value.mean_s);
            pj.set("sigma_s", p.value.sigma_s);
            preds.push_back(pj);
        }
        c.set("predictions", preds);
        cases.push_back(c);
    }
    Json tour = Json::array();
    for (std::int64_t V : {1, 2, 3, 4, 7, 9, 16, 33, 64, 100, 1000, 50257})
        for (int k : {2, 4, 8})
            for (bool wi : {false, true}) {
                const TournamentCounts tc = tournament_counts(V, k, wi);
                Json t = Json::object();
                t.set("n", static_cast<long long>(V));
                t.set("k", k);
                t.set("with_index", wi);
                t.set("levels", static_cast<long long>(tc.levels));
                t.set("rounds", static_cast<long long>(tc.rounds));
                t.set("drelu_p1", static_cast<long long>(tc.comparisons));
                t.set("drelu_p2", static_cast<long long>(tc.payload_drelu));
                t.set("beaver_select", static_cast<long long>(tc.selects));
                tour.push_back(t);
            }
    const FormulaConstants fc = formula_constants();
    Json f = Json::object();
    f.set("bfv_ct_bytes", static_cast<long long>(fc.bfv_ciphertext_bytes));
    f.set("frame_bytes", static_cast<long long>(fc.frame_bytes));
    f.set("drelu_p1_bytes", static_cast<long long>(drelu_material_bytes(nc, 1)));
    f.set("drelu_p2_bytes", static_cast<long long>(drelu_material_bytes(nc, 2)));
    f.set("trunc_faithful_bytes", static_cast<long long>(trunc_material_bytes(nc)));
    f.set("ring_to_field_bytes", static_cast<long long>(r2f_material_bytes()));
    Json root = Json::object();
    root.set("format", "opencrab2-costmodel-vectors-v1");
    root.set("origin", "cpp");
    root.set("generator", "cpp/tests/test_vectors.cpp --emit (opencrab2::highlevel::FittedCostModel)");
    root.set("comparison", "integers exactly; mean_s and sigma_s to relative 1e-9");
    root.set("model", model.to_json());
    root.set("envs", envs_j);
    root.set("formulas", f);
    root.set("cases", cases);
    root.set("tournament", tour);
    save_json(path, root);
}

static int emit_all(const std::string& dir, size_t kci_keys) {
    emit_drelu(dir + "/cpp_drelu_vectors.json", kci_keys);
    emit_codec(dir + "/cpp_codec_vectors.json");
    emit_contract(dir + "/cpp_contract_vectors.json");
    emit_costmodel(dir + "/cpp_costmodel_vectors.json");
    // the emitted files pass the checks of this executable as well (same formats as the Python files)
    if (Expected<Json> j = Json::load_file(dir + "/cpp_drelu_vectors.json"); j.ok) test_drelu(j.value);
    if (Expected<Json> j = Json::load_file(dir + "/cpp_codec_vectors.json"); j.ok) test_codec(j.value);
    if (Expected<Json> j = Json::load_file(dir + "/cpp_contract_vectors.json"); j.ok) test_contract(j.value);
    if (Expected<Json> j = Json::load_file(dir + "/cpp_costmodel_vectors.json"); j.ok) test_costmodel(j.value);
    std::printf("PASS %d checks\n", g_checks);
    return 0;
}

// ---------------------------------------------------------------------------
static std::string find_dir(const std::string& arg) {
    if (!arg.empty()) return arg;
    const char* candidates[] = {"cpp/tests/vectors", "tests/vectors", "vectors", "../tests/vectors", "../../tests/vectors"};
    for (const char* c : candidates) {
        std::ifstream probe(std::string(c) + "/dcf_vectors.json");
        if (probe) return c;
    }
    return "cpp/tests/vectors";
}

int main(int argc, char** argv) {
    std::string dir_arg, emit_dir;
    size_t kci_keys = 128;
    for (int i = 1; i < argc; ++i) {
        if (std::strcmp(argv[i], "--emit") == 0 && i + 1 < argc) emit_dir = argv[++i];
        else if (std::strcmp(argv[i], "--kci-keys") == 0 && i + 1 < argc) kci_keys = static_cast<size_t>(std::strtoull(argv[++i], nullptr, 10));
        else if (argv[i][0] == '-') {
            std::fprintf(stderr, "VECTORS_USAGE: test_vectors [vectors_dir] | --emit DIR [--kci-keys N]\n");
            return 2;
        } else dir_arg = argv[i];
    }
    if (!emit_dir.empty()) {
        if (kci_keys < 1 || kci_keys > 100000) {
            std::fprintf(stderr, "VECTORS_USAGE: --kci-keys must be in [1, 100000]\n");
            return 2;
        }
        return emit_all(emit_dir, kci_keys);
    }
    const std::string dir = find_dir(dir_arg);
    std::printf("[test_vectors] directory %s\n", dir.c_str());
    if (Expected<Json> j = load_or_skip(dir, "prg_vectors.json"); j.ok) test_prg(j.value);
    if (Expected<Json> j = load_or_skip(dir, "dcf_vectors.json"); j.ok) test_dcf(j.value);
    if (Expected<Json> j = load_or_skip(dir, "drelu_vectors.json"); j.ok) test_drelu(j.value);
    if (Expected<Json> j = load_or_skip(dir, "trunc_vectors.json"); j.ok) test_trunc(j.value);
    if (Expected<Json> j = load_or_skip(dir, "r2f_vectors.json"); j.ok) test_r2f(j.value);
    if (Expected<Json> j = load_or_skip(dir, "controller_vectors.json"); j.ok) test_controller(j.value);
    if (Expected<Json> j = load_or_skip(dir, "codec_vectors.json"); j.ok) test_codec(j.value);
    if (Expected<Json> j = load_or_skip(dir, "contract_vectors.json"); j.ok) test_contract(j.value);
    if (Expected<Json> j = load_or_skip(dir, "costmodel_vectors.json"); j.ok) test_costmodel(j.value);
    if (Expected<Json> j = load_or_skip(dir, "shaper_vectors.json"); j.ok) test_shaper(j.value);
    if (Expected<Json> j = load_or_skip(dir, "telemetry_vectors.json"); j.ok) test_telemetry(j.value);
    if (g_skipped_files == g_wanted_files) {
        // nothing was compared: a wrong directory must not count as a pass
        std::printf("FAIL: no vector file found in %s (pass the directory of the vector files: test_vectors cpp/tests/vectors)\n", dir.c_str());
        return 1;
    }
    if (g_skipped_files > 0) std::printf("  %d vector file(s) skipped\n", g_skipped_files);
    std::printf("PASS %d checks\n", g_checks);
    return 0;
}
